import { readFileSync, existsSync, statSync } from 'node:fs'
import { join, resolve } from 'node:path'

/**
 * Review artifacts are an engineering delivery contract, not a screenshot
 * generated by an undocumented manual action. Failure = missing frame/sheet.
 */
const root = resolve(process.cwd(), '.review/m1-s2/generated')
const required = [
  '01-work-orders', '02-appointment',
  '03-survey-overview', '03-survey-parts', '03-survey-parts-selected', '04-survey-filled', '04-survey-media', '04-survey-reasons', '04-survey-reasons-selected',
  '05-quote-entry', '06-quote-catalog', '07-quote-group',
  '08-signing-empty', '09-signing-progress', '10-signing-expired',
  '11-signing-actual-order', '12-signing-actual-contract',
]
let failures = 0

function fail(msg) {
  console.error('[s2-ux-sheet] ' + msg)
  failures += 1
}
function png(filename) {
  if (!existsSync(filename) || statSync(filename).size < 2000) {
    fail('missing or suspiciously small PNG: ' + filename)
    return
  }
  const bytes = readFileSync(filename)
  if (!bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))) {
    fail('invalid PNG header: ' + filename)
  }
}
for (const size of ['390x844', '375x667']) {
  const dir = join(root, size)
  const manifestPath = join(dir, 'manifest.json')
  if (!existsSync(manifestPath)) {
    fail('missing ' + size + '/manifest.json')
    continue
  }
  const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'))
  if (manifest.schemaVersion !== 1 || manifest.provenance !== 'DEV_ONLY_SOURCE_MODELED_MOCK'
    || manifest.actualApp !== true || manifest.frameCount !== required.length) {
    fail('invalid provenance or frame count for ' + size)
  }
  const ids = manifest.frames?.map(frame => frame.id) ?? []
  if (JSON.stringify(ids) !== JSON.stringify(required)) {
    fail('frame order changed for ' + size + ': ' + JSON.stringify(ids))
  }
  for (const frame of manifest.frames ?? []) {
    if (frame.path?.includes('http') || !frame.path?.startsWith('#/pages/')) {
      fail('unexpected page route ' + frame.path)
    }
    if (!['accepted_baseline', 'review_candidate'].includes(frame.status)) {
      fail('invalid review status ' + frame.id)
    }
    png(join(dir, frame.file))
  }
  for (const id of required.slice(0, 2)) {
    const frame = manifest.frames?.find(item => item.id === id)
    if (frame?.status !== 'accepted_baseline') fail('missing approved UX baseline: ' + id)
  }
  if (!existsSync(join(dir, 'index.html'))) fail('missing offline HTML review index for ' + size)
  png(join(dir, 'review-sheet.png'))
}
if (failures) {
  console.error('[s2-ux-sheet] FAILED: ' + failures + ' artifact contract violations')
  process.exit(1)
}
console.log('[s2-ux-sheet] PASS: two viewports, 34 ordered real-App screenshots, 2 PNG sheets, manifests and HTML index')
